mapper.select:
SELECT FROM plt_dynamic_form_instance i JOIN plt_dynamic_form_template t ON t.tenant_id = i.tenant_id AND t.id = i.template_id AND t.deleted = b'0' WHERE i.tenant_id = #{query.tenantId} AND i.deleted = b'0'
AND i.instance_name LIKE CONCAT('%', #{query.instanceNameKeyword}, '%')
AND i.created_by = #{query.createdBy}
ORDER BY i.update_time DESC, i.id DESC LIMIT #{query.limit} OFFSET #{query.offset}

SELECT COUNT(*) FROM plt_dynamic_form_instance i WHERE i.tenant_id = #{query.tenantId} AND i.deleted = b'0'
AND i.instance_name LIKE CONCAT('%', #{query.instanceNameKeyword}, '%')
AND i.created_by = #{query.createdBy}
